const input = $json.body ?? $json;
const ticket = {
  ticketId: String(input.ticketId ?? input.id ?? `T-${Date.now()}`),
  customerName: String(input.customerName ?? "Customer"),
  email: String(input.email ?? ""),
  subject: String(input.subject ?? "Support request"),
  message: String(input.message ?? input.description ?? ""),
  orderId: String(input.orderId ?? ""),
  plan: String(input.plan ?? "Free")
};
if (!ticket.message.trim()) throw new Error("Ticket message is required");
return { json: { ticket, workflow: { revisionCount: 0 } } };

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("AI 1 returned no content");
const triage = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/, "").trim());
const original = $("Normalize Ticket").item.json;
return { json: { ...original, triage } };

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("AI 2 returned no content");
const result = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/, "").trim());
return { json: { draftReply: result.draftReply ?? "" } };

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("AI 3 returned no content");
const result = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/, "").trim());
return { json: { internalNote: result.internalNote ?? "" } };

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("AI 4 returned no content");
const review = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/, "").trim());
const merged = $("Merge Reply + Note").item.json;
const triage = $("Parse Triage").item.json;
return { json: { ...triage, ...merged, review, workflow: { revisionCount: 0 } } };

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("AI 5 returned no content");
const result = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/, "").trim());
const previous = $("Approved?").item.json;
return { json: { ...previous, draftReply: result.revisedReply ?? previous.draftReply, workflow: { revisionCount: 1 } } };

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("Re-review returned no content");
const review = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/, "").trim());
const revised = $("Parse Revised Reply").item.json;
return { json: { ...revised, review } };

const d = $json;
const humanReview = d.triage.needsHumanReview === true;
return { json: { ticketId: d.ticket.ticketId, category: d.triage.category, priority: d.triage.priority, decision: humanReview ? "HUMAN_REVIEW_REQUIRED" : "APPROVED_FOR_AGENT_SEND", customerReply: d.draftReply, internalNote: d.internalNote, triage: d.triage, review: d.review, revisionCount: 0, note: humanReview ? "Sensitive/legal/security/payment-risk tickets must be handled by a human." : "Approved by AI review. This workflow does not send email automatically." } };

const d = $json;
const approved = d.review.approved === true && d.triage.needsHumanReview !== true;
return { json: { ticketId: d.ticket.ticketId, category: d.triage.category, priority: d.triage.priority, decision: approved ? "APPROVED_FOR_AGENT_SEND" : "HUMAN_REVIEW_REQUIRED", customerReply: d.draftReply, internalNote: d.internalNote, triage: d.triage, review: d.review, revisionCount: 1, note: approved ? "Revised reply passed review. This workflow does not send email automatically." : "Revised reply did not pass review or ticket is sensitive; human review is required before sending." } };
